-- Healthcarology EHR baseline derived from the four supplied Word documents.
-- No live project was supplied, so this migration is generated but not applied.

create table public.countries (id bigint generated by default as identity primary key, iso2 char(2) unique not null, iso3 char(3) unique not null, numeric_code integer, default_name text not null, active boolean not null default true);
create table public.provinces (id bigint generated by default as identity primary key, country_id bigint not null references public.countries(id) on delete cascade, code text, default_name text not null, type text);
create table public.cities (id bigint generated by default as identity primary key, country_id bigint not null references public.countries(id) on delete cascade, province_id bigint references public.provinces(id), default_name text not null, latitude numeric(9,6), longitude numeric(9,6));
create table public.postal_codes (id bigint generated by default as identity primary key, country_id bigint not null references public.countries(id) on delete cascade, province_id bigint references public.provinces(id), city_id bigint references public.cities(id), code text not null, area_name text);
create table public.translations (id bigint generated by default as identity primary key, entity_type text not null check (entity_type in ('country','province','city','postal_code')), entity_id bigint not null, locale text not null, name text not null, unique(entity_type,entity_id,locale));
create table public.addresses (id bigint generated by default as identity primary key, line1 text not null, line2 text, city_id bigint references public.cities(id), province_id bigint references public.provinces(id), country_id bigint not null references public.countries(id), postal_code_id bigint references public.postal_codes(id), postal_code_text text, latitude numeric(9,6), longitude numeric(9,6));

create table public.departments (id bigint generated by default as identity primary key, code text unique not null, name text not null, type text);
create table public.services (id bigint generated by default as identity primary key, department_id bigint not null references public.departments(id) on delete cascade, name text not null, service_type text);
create table public.locations (id bigint generated by default as identity primary key, service_id bigint references public.services(id), name text not null, address_id bigint references public.addresses(id));

create table public.person_categories (id bigint generated by default as identity primary key, code text unique not null, description text not null);
create table public.patients (id bigint generated by default as identity primary key, snau text unique, mrn text unique, first_name text not null, middle_name text, last_name text not null, sex text, date_of_birth date, birth_province_id bigint references public.provinces(id), birth_city_id bigint references public.cities(id), category_id bigint references public.person_categories(id), life_status text, registration_source text, primary_address_id bigint references public.addresses(id), mailing_address_id bigint references public.addresses(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index patients_name_birth_idx on public.patients(last_name, first_name, date_of_birth);
create table public.family_links (id bigint generated by default as identity primary key, main_patient_id bigint not null references public.patients(id) on delete cascade, dependent_patient_id bigint not null references public.patients(id) on delete cascade, link_type text not null, dependent_code smallint check (dependent_code in (1,2)), unique(main_patient_id,dependent_patient_id));

create table public.roles (id bigint generated by default as identity primary key, role_code text unique not null, role_name text not null, description text, access_level smallint check(access_level between 0 and 6));
create table public.role_permissions (role_id bigint primary key references public.roles(id) on delete cascade, view_demographics text not null default 'none' check(view_demographics in ('full','limited','none')), view_clinical text not null default 'none' check(view_clinical in ('full','limited','none')), edit_clinical text not null default 'none' check(edit_clinical in ('full','limited','none')), order_prescribe text not null default 'none' check(order_prescribe in ('full','limited','none')), billing_access text not null default 'none' check(billing_access in ('full','limited','none')), admin_users text not null default 'none' check(admin_users in ('full','limited','none')), system_config text not null default 'none' check(system_config in ('full','limited','none')), audit_logs text not null default 'none' check(audit_logs in ('full','limited','none')));
create table public.user_roles (user_id uuid not null references auth.users(id) on delete cascade, role_id bigint not null references public.roles(id) on delete cascade, scope text, primary key(user_id,role_id));
create table public.providers (id bigint generated by default as identity primary key, user_id uuid unique references auth.users(id) on delete set null, provider_type text not null, department_id bigint references public.departments(id), service_id bigint references public.services(id), active boolean not null default true);

create table public.encounters (id bigint generated by default as identity primary key, patient_id bigint not null references public.patients(id) on delete cascade, encounter_type text not null, service_id bigint references public.services(id), location_id bigint references public.locations(id), start_at timestamptz not null, end_at timestamptz, attending_provider_id bigint references public.providers(id), status text not null default 'open' check(status in ('open','closed','cancelled')));
create table public.orders (id bigint generated by default as identity primary key, patient_id bigint not null references public.patients(id) on delete cascade, encounter_id bigint references public.encounters(id), ordering_provider_id bigint references public.providers(id), order_type text not null check(order_type in ('lab','imaging','procedure','medication')), service_id bigint references public.services(id), status text not null default 'pending' check(status in ('pending','in_progress','completed','cancelled')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.lab_orders (id bigint generated by default as identity primary key, order_id bigint unique not null references public.orders(id) on delete cascade, test_code text not null, priority text, specimen_type text);
create table public.imaging_orders (id bigint generated by default as identity primary key, order_id bigint unique not null references public.orders(id) on delete cascade, modality text not null, body_part text, contrast boolean);
create table public.procedure_orders (id bigint generated by default as identity primary key, order_id bigint unique not null references public.orders(id) on delete cascade, procedure_code text not null, scheduled_at timestamptz, location_id bigint references public.locations(id));
create table public.lab_results (id bigint generated by default as identity primary key, lab_order_id bigint not null references public.lab_orders(id) on delete cascade, result_at timestamptz, result_status text, analyte_code text, value text, units text, reference_range text, abnormal_flag text);
create table public.imaging_results (id bigint generated by default as identity primary key, imaging_order_id bigint not null references public.imaging_orders(id) on delete cascade, result_at timestamptz, result_status text, report_text text, radiologist_id bigint references public.providers(id));
create table public.procedure_results (id bigint generated by default as identity primary key, procedure_order_id bigint not null references public.procedure_orders(id) on delete cascade, performed_at timestamptz, result_status text, report_text text, performing_provider_id bigint references public.providers(id));

create table public.medications (id bigint generated by default as identity primary key, name text not null, generic_name text, strength text, form text, route text);
create table public.medication_orders (id bigint generated by default as identity primary key, patient_id bigint not null references public.patients(id) on delete cascade, encounter_id bigint references public.encounters(id), prescriber_id bigint references public.providers(id), medication_id bigint not null references public.medications(id), dose text not null, route text, frequency text, start_at timestamptz, end_at timestamptz, status text not null default 'active' check(status in ('active','completed','cancelled','on_hold')));
create table public.medication_administrations (id bigint generated by default as identity primary key, medication_order_id bigint not null references public.medication_orders(id) on delete cascade, administered_at timestamptz not null, administering_provider_id bigint references public.providers(id), dose_given text, route text, notes text);
create table public.clinical_notes (id bigint generated by default as identity primary key, patient_id bigint not null references public.patients(id) on delete cascade, encounter_id bigint references public.encounters(id), author_provider_id bigint references public.providers(id), note_type text not null, content text not null, created_at timestamptz not null default now(), signed_at timestamptz, status text not null default 'draft' check(status in ('draft','signed','amended')));

create table public.patient_accounts (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, patient_id bigint not null references public.patients(id) on delete cascade, unique(user_id,patient_id));
create table public.patient_proxies (id bigint generated by default as identity primary key, proxy_patient_id bigint not null references public.patients(id) on delete cascade, target_patient_id bigint not null references public.patients(id) on delete cascade, relationship text not null, can_view boolean not null default true, can_message boolean not null default true, can_manage_appointments boolean not null default false, active boolean not null default true, unique(proxy_patient_id,target_patient_id));
create table public.audit_logs (id bigint generated by default as identity primary key, patient_id bigint references public.patients(id) on delete set null, action_type text not null, actor_user_id uuid references auth.users(id) on delete set null, actor_type text not null, occurred_at timestamptz not null default now(), context text, reason text);

-- Authorization claims are read from app_metadata, not user-editable user_metadata.
create or replace function public.current_role_code() returns text language sql stable security invoker set search_path='' as $$ select coalesce((select auth.jwt()->'app_metadata'->>'role'),'') $$;
create or replace function public.current_provider_id() returns bigint language sql stable security invoker set search_path='' as $$ select nullif((select auth.jwt()->'app_metadata'->>'provider_id'),'')::bigint $$;
revoke all on function public.current_role_code() from public;
revoke all on function public.current_provider_id() from public;
grant execute on function public.current_role_code() to authenticated;
grant execute on function public.current_provider_id() to authenticated;

alter table public.countries enable row level security; alter table public.provinces enable row level security; alter table public.cities enable row level security; alter table public.postal_codes enable row level security; alter table public.translations enable row level security; alter table public.addresses enable row level security; alter table public.departments enable row level security; alter table public.services enable row level security; alter table public.locations enable row level security; alter table public.person_categories enable row level security; alter table public.patients enable row level security; alter table public.family_links enable row level security; alter table public.roles enable row level security; alter table public.role_permissions enable row level security; alter table public.user_roles enable row level security; alter table public.providers enable row level security; alter table public.encounters enable row level security; alter table public.orders enable row level security; alter table public.lab_orders enable row level security; alter table public.imaging_orders enable row level security; alter table public.procedure_orders enable row level security; alter table public.lab_results enable row level security; alter table public.imaging_results enable row level security; alter table public.procedure_results enable row level security; alter table public.medications enable row level security; alter table public.medication_orders enable row level security; alter table public.medication_administrations enable row level security; alter table public.clinical_notes enable row level security; alter table public.patient_accounts enable row level security; alter table public.patient_proxies enable row level security; alter table public.audit_logs enable row level security;

create policy countries_read on public.countries for select to anon,authenticated using(true);
create policy provinces_read on public.provinces for select to anon,authenticated using(true);
create policy cities_read on public.cities for select to anon,authenticated using(true);
create policy postal_codes_read on public.postal_codes for select to anon,authenticated using(true);
create policy translations_read on public.translations for select to anon,authenticated using(true);
create policy user_roles_self_read on public.user_roles for select to authenticated using((select auth.uid())=user_id);
create policy patient_accounts_self_read on public.patient_accounts for select to authenticated using((select auth.uid())=user_id);
create policy patients_staff_read on public.patients for select to authenticated using(public.current_role_code() in ('physician','nurse','pharmacist','therapist','lab_tech','rad_tech','billing','him','compliance','sysadmin'));
create policy patients_portal_read on public.patients for select to authenticated using(public.current_role_code()='patient' and (exists(select 1 from public.patient_accounts pa where pa.user_id=(select auth.uid()) and pa.patient_id=patients.id) or exists(select 1 from public.patient_accounts pa join public.patient_proxies px on px.proxy_patient_id=pa.patient_id where pa.user_id=(select auth.uid()) and px.target_patient_id=patients.id and px.can_view and px.active)));
create policy encounters_staff_read on public.encounters for select to authenticated using(public.current_role_code() in ('physician','nurse','pharmacist','therapist','lab_tech','rad_tech','him','compliance'));
create policy encounters_portal_read on public.encounters for select to authenticated using(public.current_role_code()='patient' and exists(select 1 from public.patients p where p.id=encounters.patient_id));
create policy clinical_notes_staff_read on public.clinical_notes for select to authenticated using(public.current_role_code() in ('physician','nurse','therapist','him','compliance'));
create policy clinical_notes_author_insert on public.clinical_notes for insert to authenticated with check(public.current_role_code() in ('physician','nurse','therapist') and author_provider_id=public.current_provider_id());
create policy audit_oversight_read on public.audit_logs for select to authenticated using(public.current_role_code() in ('him','compliance','sysadmin'));

-- New Supabase projects may not expose new public tables automatically. Grant only
-- after reviewing Data API settings; RLS still controls rows after these grants.
grant select on public.countries, public.provinces, public.cities, public.postal_codes, public.translations to anon, authenticated;
grant select on public.user_roles, public.patient_accounts, public.patients, public.encounters, public.clinical_notes, public.audit_logs to authenticated;
grant insert on public.clinical_notes to authenticated;
